/* ---------- thinking ---------- */
{
  const head = $('#tk2-h'), fold = $('#tk2-fold'), list = $('#tk2-list'), title = $('#tk2-t');
  const D = {
    steps:[['Reading the brief',''],['Scanning the design file','12 frames'],['Comparing against the tokens','4 issues'],['Writing the summary','']],
    search:[['Searched "pricing page patterns"','8 results'],['Searched "plan comparison tables"','6 results'],['Read 3 pages','']],
    coding:[['Edited PricingCard.tsx','+24 −9'],['Edited tokens.css','+6 −2'],['Ran type check','Passed']],
    reasoning:'The comparison table sits below the fold, so most visitors pick a plan before they see what is included. Moving it above the plans answers the common questions first and keeps the page the same length.'
  };
  let ts = [], t0 = 0;
  const clear = () => { ts.forEach(clearTimeout); ts = []; };
  const tickLast = () => { const prev = list.lastElementChild; if (prev && prev.querySelector('.st')) prev.querySelector('.st').innerHTML = ic('check', 'sm icon-in'); };
  function done(){ const s = Math.max(1, Math.round((performance.now() - t0) / 1000)); title.classList.remove('shimmer'); swapText(title, `Thought for ${s} second${s === 1 ? '' : 's'}`); ambient('c60', 'done'); }
  function run(v){
    clear(); list.innerHTML = ''; title.classList.add('shimmer'); title.textContent = 'Thinking'; t0 = performance.now();
    if (v === 'reasoning'){
      const p = document.createElement('div'); p.className = 'tk2-p'; p.innerHTML = wordsHTML(D.reasoning); list.appendChild(p);
      const r = revealWords(p, 45, i => { if (i % 3 === 0) ambient('c60', 'stream'); });
      ts.push(setTimeout(done, r.done + 300)); return;
    }
    D[v].forEach((it, i) => ts.push(setTimeout(() => {
      tickLast();
      const row = document.createElement('div'); row.className = 'tk2-row';
      row.innerHTML = `<span class="st"><i class="spin"></i></span><span>${it[0]}</span>${it[1] ? `<span class="m">${it[1]}</span>` : ''}`;
      list.appendChild(row); ambient('c60', 'tick');
    }, 250 + i * 900)));
    ts.push(setTimeout(() => { tickLast(); done(); }, 250 + D[v].length * 900));
  }
  head.addEventListener('click', () => { const open = head.getAttribute('aria-expanded') !== 'true'; head.setAttribute('aria-expanded', open); fold.classList.toggle('open', open); Sound.play(open ? 'open' : 'close'); });
  tabHandlers.tk2 = v => { head.setAttribute('aria-expanded', 'true'); fold.classList.add('open'); run(v); };
  whenSeen($('#c60'), () => run('steps'));
}
